/**
 * @file sdcard.ino
 * @author SeanKwok (shaoxiang@m5stack.com)
 * @brief M5Cardputer MicroSD Card Test
 * @version 0.1
 * @date 2024-01-19
 *
 *
 * @Hardwares: M5Cardputer
 * @Platform Version: Arduino M5Stack Board Manager v2.1.0
 * @Dependent Library:
 * M5GFX: https://github.com/m5stack/M5GFX
 * M5Unified: https://github.com/m5stack/M5Unified
 * M5Cardputer: https://github.com/m5stack/M5Cardputer
 */

#include <M5Cardputer.h>
#include <SPI.h>
#include <SD.h>

#define SD_SPI_SCK_PIN  40
#define SD_SPI_MISO_PIN 39
#define SD_SPI_MOSI_PIN 14
#define SD_SPI_CS_PIN   12

void listDir(fs::FS &fs, const char *dirname, uint8_t levels);
void createDir(fs::FS &fs, const char *path);
void removeDir(fs::FS &fs, const char *path);
void readFile(fs::FS &fs, const char *path);
void writeFile(fs::FS &fs, const char *path, const char *message);
void appendFile(fs::FS &fs, const char *path, const char *message);
void renameFile(fs::FS &fs, const char *path1, const char *path2);
void deleteFile(fs::FS &fs, const char *path);
void testFileIO(fs::FS &fs, const char *path);

M5Canvas canvas(&M5Cardputer.Display);

void printf_log(const char *format, ...);
void println_log(const char *str);

void setup() {
    M5Cardputer.begin();
    M5Cardputer.Display.setRotation(1);
    canvas.setColorDepth(1);  // mono color
    canvas.createSprite(M5Cardputer.Display.width(),
                        M5Cardputer.Display.height());
    canvas.setPaletteColor(1, GREEN);
    canvas.setTextSize((float)canvas.width() / 160);
    canvas.setTextScroll(true);

    // SD Card Initialization
    SPI.begin(SD_SPI_SCK_PIN, SD_SPI_MISO_PIN, SD_SPI_MOSI_PIN, SD_SPI_CS_PIN);

    if (!SD.begin(SD_SPI_CS_PIN, SPI, 25000000)) {
        // Print a message if the SD card initialization
        // fails orif the SD card does not exist.
        // 如果SD卡初始化失败或者SD卡不存在，则打印消息.
        println_log("Card failed, or not present");
        while (1)
            ;
    }

    uint8_t cardType = SD.cardType();

    if (cardType == CARD_NONE) {
        println_log("No SD card attached");
        return;
    }

    Serial.print("SD Card Type: ");
    if (cardType == CARD_MMC) {
        println_log("MMC");
    } else if (cardType == CARD_SD) {
        println_log("SDSC");
    } else if (cardType == CARD_SDHC) {
        println_log("SDHC");
    } else {
        println_log("UNKNOWN");
    }

    uint64_t cardSize = SD.cardSize() / (1024 * 1024);
    printf_log("SD Card Size: %lluMB\n", cardSize);

    listDir(SD, "/", 0);
    createDir(SD, "/mydir");
    listDir(SD, "/", 0);
    removeDir(SD, "/mydir");
    listDir(SD, "/", 2);
    writeFile(SD, "/hello.txt", "Hello ");
    appendFile(SD, "/hello.txt", "World!\n");
    readFile(SD, "/hello.txt");
    deleteFile(SD, "/foo.txt");
    renameFile(SD, "/hello.txt", "/foo.txt");
    readFile(SD, "/foo.txt");
    testFileIO(SD, "/test.txt");
    printf_log("Total space: %lluMB\n", SD.totalBytes() / (1024 * 1024));
    printf_log("Used space: %lluMB\n", SD.usedBytes() / (1024 * 1024));
}
void loop() {
}

void listDir(fs::FS &fs, const char *dirname, uint8_t levels) {
    printf_log("Listing directory: %s\n", dirname);

    File root = fs.open(dirname);
    if (!root) {
        println_log("Failed to open directory");
        return;
    }
    if (!root.isDirectory()) {
        println_log("Not a directory");
        return;
    }

    File file = root.openNextFile();
    while (file) {
        if (file.isDirectory()) {
            Serial.print("  DIR : ");
            println_log(file.name());
            if (levels) {
                listDir(fs, file.path(), levels - 1);
            }
        } else {
            Serial.print("  FILE: ");
            Serial.print(file.name());
            Serial.print("  SIZE: ");
            println_log(String(file.size()).c_str());
        }
        file = root.openNextFile();
    }
}

void createDir(fs::FS &fs, const char *path) {
    printf_log("Creating Dir: %s\n", path);
    if (fs.mkdir(path)) {
        println_log("Dir created");
    } else {
        println_log("mkdir failed");
    }
}

void removeDir(fs::FS &fs, const char *path) {
    printf_log("Removing Dir: %s\n", path);
    if (fs.rmdir(path)) {
        println_log("Dir removed");
    } else {
        println_log("rmdir failed");
    }
}

void readFile(fs::FS &fs, const char *path) {
    printf_log("Reading file: %s\n", path);

    File file = fs.open(path);
    if (!file) {
        println_log("Failed to open file for reading");
        return;
    }

    Serial.print("Read from file: ");
    while (file.available()) {
        Serial.write(file.read());
    }
    file.close();
}

void writeFile(fs::FS &fs, const char *path, const char *message) {
    printf_log("Writing file: %s\n", path);

    File file = fs.open(path, FILE_WRITE);
    if (!file) {
        println_log("Failed to open file for writing");
        return;
    }
    if (file.print(message)) {
        println_log("File written");
    } else {
        println_log("Write failed");
    }
    file.close();
}

void appendFile(fs::FS &fs, const char *path, const char *message) {
    printf_log("Appending to file: %s\n", path);

    File file = fs.open(path, FILE_APPEND);
    if (!file) {
        println_log("Failed to open file for appending");
        return;
    }
    if (file.print(message)) {
        println_log("Message appended");
    } else {
        println_log("Append failed");
    }
    file.close();
}

void renameFile(fs::FS &fs, const char *path1, const char *path2) {
    printf_log("Renaming file %s to %s\n", path1, path2);
    if (fs.rename(path1, path2)) {
        println_log("File renamed");
    } else {
        println_log("Rename failed");
    }
}

void deleteFile(fs::FS &fs, const char *path) {
    printf_log("Deleting file: %s\n", path);
    if (fs.remove(path)) {
        println_log("File deleted");
    } else {
        println_log("Delete failed");
    }
}

void testFileIO(fs::FS &fs, const char *path) {
    File file = fs.open(path);
    static uint8_t buf[512];
    size_t len     = 0;
    uint32_t start = millis();
    uint32_t end   = start;
    if (file) {
        len         = file.size();
        size_t flen = len;
        start       = millis();
        while (len) {
            size_t toRead = len;
            if (toRead > 512) {
                toRead = 512;
            }
            file.read(buf, toRead);
            len -= toRead;
        }
        end = millis() - start;
        printf_log("%u bytes read for %lu ms\n", flen, end);
        file.close();
    } else {
        println_log("Failed to open file for reading");
    }

    file = fs.open(path, FILE_WRITE);
    if (!file) {
        println_log("Failed to open file for writing");
        return;
    }

    size_t i;
    start = millis();
    for (i = 0; i < 2048; i++) {
        file.write(buf, 512);
    }
    end = millis() - start;
    printf_log("%u bytes written for %lu ms\n", 2048 * 512, end);
    file.close();
}

void printf_log(const char *format, ...) {
    char buf[256];
    va_list args;
    va_start(args, format);
    vsnprintf(buf, 256, format, args);
    va_end(args);
    Serial.print(buf);
    canvas.printf(buf);
    canvas.pushSprite(0, 0);
}

void println_log(const char *str) {
    Serial.println(str);
    canvas.println(str);
    canvas.pushSprite(0, 0);
}

// 音效播放器：M5Unified Speaker 非阻塞音符序列。
// 每个 Claude Code hook 事件对应一段短旋律，在主 loop() 的 tick() 中推进。
#pragma once

namespace sound {
void begin();               // 初始化音量（M5Cardputer.begin() 之后调）
void tick();                // 每帧推进序列，call in loop()
void play(const char* name); // "approval" "done" "tool" "stop_fail"
                             // "connect" "disconnect" "nudge"
bool busy();                // 当前是否在播放
void playEvent(const char* name);  // 播放 /sounds/<name>.wav（hook 事件，文件不存在则忽略）
void volumeUp();                   // 音量 +25（= 键）
void volumeDown();                 // 音量 -25（- 键）
int  volume();                     // 当前音量 0-255
}

// 音效播放器实现。
// 每段旋律存为 Note 数组（freq=0 表示序列结束），tick() 检测 isPlaying() 推进下一音符。
// tone(freq, ms) 由 M5Unified DMA 后台播放，不阻塞主循环。
#include "sound_player.h"
#include "M5Cardputer.h"
#include <LittleFS.h>
#include <string.h>

namespace {
struct Note { uint16_t freq; uint16_t ms; };

// 各事件旋律（音符频率 Hz + 持续 ms，freq=0 结束）
// A5=880 B5=988 C6=1047 D6=1175 E6=1319
static const Note SND_APPROVAL[]   = {{880,130},{1047,130},{1319,230},{0,0}};  // A5-C6-E6 警示三音
static const Note SND_DONE[]       = {{880,90},{1047,90},{1175,90},{1319,260},{0,0}}; // 完成四音上行
static const Note SND_TOOL[]       = {{1047,40},{0,0}};  // C6 短促点击
static const Note SND_STOP_FAIL[]  = {{1047,130},{880,130},{698,220},{0,0}};   // 下行三音
static const Note SND_CONNECT[]    = {{880,120},{1319,200},{0,0}};  // A5-E6 上行欢迎
static const Note SND_DISCONNECT[] = {{1319,120},{880,180},{0,0}};  // E6-A5 下行告别
static const Note SND_NUDGE[]      = {{1175,30},{0,0}};  // D6 触感

const Note* g_seq = nullptr;
int         g_idx = 0;
uint32_t    g_playAfterMs = 0;  // millis() 时间戳，到了才允许播放（开机延迟）

int      g_volume = 25;         // 初始音量 0-255（-/= 键步进 25，tone 与 wav 共用）
uint8_t* g_wavBuf = nullptr;    // wav 读入缓冲（复用；playWav 异步播放期间不可覆盖）
size_t   g_wavCap = 0;
}  // namespace

namespace sound {

void begin() {
    M5Cardputer.Speaker.setVolume(g_volume);
    g_seq = SND_CONNECT;
    g_idx = 0;
    g_playAfterMs = 800;  // 开机 800ms 后播（等 DAC+BLE 稳定）
}

void play(const char* name) {
    const Note* seq = nullptr;
    if      (strcmp(name, "approval")    == 0) seq = SND_APPROVAL;
    else if (strcmp(name, "done")        == 0) seq = SND_DONE;
    else if (strcmp(name, "tool")        == 0) seq = SND_TOOL;
    else if (strcmp(name, "stop_fail")   == 0) seq = SND_STOP_FAIL;
    else if (strcmp(name, "connect")     == 0) seq = SND_CONNECT;
    else if (strcmp(name, "disconnect")  == 0) seq = SND_DISCONNECT;
    else if (strcmp(name, "nudge")       == 0) seq = SND_NUDGE;
    if (!seq) return;
    M5Cardputer.Speaker.stop();
    g_seq = seq;
    g_idx = 0;
}

bool busy() { return g_seq != nullptr; }

// 播放 hook 事件 wav：从 LittleFS 读 /sounds/<name>.wav 到 RAM → playWav(异步)。
// 文件不存在则 no-op —— 只有关键事件放了 wav，bridge 发的其他 play 字段自动忽略。
void playEvent(const char* name) {
    if (!name || !name[0]) return;
    char path[48];
    snprintf(path, sizeof(path), "/sounds/%s.wav", name);
    File f = LittleFS.open(path, "r");
    if (!f) return;
    size_t len = f.size();
    if (len == 0 || len > 100 * 1024) { f.close(); return; }  // RAM 保护(空闲~142KB)
    if (len > g_wavCap) {                                       // 复用缓冲,只在变大时重分配
        free(g_wavBuf);
        g_wavBuf = (uint8_t*)malloc(len);
        g_wavCap = g_wavBuf ? len : 0;
    }
    if (!g_wavBuf) { f.close(); return; }
    f.read(g_wavBuf, len);
    f.close();
    M5Cardputer.Speaker.stop();
    M5Cardputer.Speaker.playWav(g_wavBuf, len);
}

void volumeUp()   { g_volume = g_volume + 25 > 255 ? 255 : g_volume + 25; M5Cardputer.Speaker.setVolume(g_volume); M5Cardputer.Speaker.tone(1175, 40); }
void volumeDown() { g_volume = g_volume - 25 < 0   ? 0   : g_volume - 25; M5Cardputer.Speaker.setVolume(g_volume); M5Cardputer.Speaker.tone(880, 40); }
int  volume()     { return g_volume; }

void tick() {
    if (g_playAfterMs > 0) {
        if (millis() < g_playAfterMs) return;
        g_playAfterMs = 0;
    }
    if (!g_seq) return;
    if (M5Cardputer.Speaker.isPlaying()) return;  // 等当前音符结束
    const Note& n = g_seq[g_idx];
    if (n.freq == 0) { g_seq = nullptr; return; }
    M5Cardputer.Speaker.tone(n.freq, n.ms);
    g_idx++;
}

}  // namespace sound

// clawd 显示层（合成器）。四种模式合成到一块 240x135 sprite 后 push：
//   NORMAL   ：clawd GIF + 右上角会话计数角标
//   APPROVAL ：审批面板（工具+参数+按键提示），覆盖 GIF
//   SESSIONS ：只读会话列表
//   HELP     ：键位说明覆盖层
// 优先级 APPROVAL > SESSIONS > HELP > NORMAL。GIF 渲染逐字复用 buddy 家族 AnimatedGIF 思路。
#pragma once
#include "agent_state.h"
#include "link_state.h"   // BuddyState / SessionInfo（会话切换器用）
#include <stdint.h>

namespace clawd {
void begin();
bool ok();

// NORMAL 模式
void setState(AgentState s);              // 会话状态 → clawd GIF
void setBadge(int total, int running);    // 右上角 "T·R" 角标
void setBattery(int pct);                  // 顶栏电量 %（<0=unknown 不显示）。openspec cardputer-battery-indicator
// 多会话轮播：顶栏左显示当前会话标识 + [idx/total]；pinned=true 时底部钉态横幅。
// total<=0 或 tag 空 = 不显示（单聚合态）。openspec change cardputer-session-rotation。
void setSessionTag(const char* tag, int idx, int total, bool pinned);
void setToast(const char* text);          // 底部短暂提示(~1.5s,nudge 发送反馈)
void setSleeping(bool sleep);
void setOnline(bool on);                   // BLE 是否连上 cc-bridge；!on 时顶栏常驻 Connecting...
void reactHeart();
void reactDizzy();
void reactError();                        // 工具出错临时动画(error-120.gif, ~2.5s)

// APPROVAL 覆盖层
void showApproval(const char* tool, const char* hint);
void hideApproval();
bool approvalVisible();

// SESSIONS 覆盖层（per-session 可选中列表 → 物理 session 切换器）
void showSessions(const BuddyState& bs);  // 用 bs.sessions[] 渲染可选中列表
void hideSessions();
void sessionsMove(int delta);             // 移动选中项（viewport 跟随）
const char* sessionsSelectedSid();        // 当前选中会话的 sid（""=无）
bool sessionsVisible();

// QUESTION 覆盖层（AskUserQuestion 应答器）
void showQuestion(const BuddyState& bs);  // 用 bs.question 渲染选项面板（快照 rid+options+multi）
void hideQuestion();
void questionMove(int delta);             // 移动光标（viewport 跟随）
void questionToggle();                    // multiSelect: toggle 当前项勾选；单选: no-op
void questionJumpTo(int idx);             // 数字键直跳到第 idx 项（0-based）
bool questionMulti();                     // 是否 multiSelect
const char* questionRid();                // 当前问题 rid（""=无）
uint8_t questionSelectedIds(const char** out, uint8_t maxN);  // 收集提交 id（单选=光标项；多选=勾选项）
bool questionVisible();

// HELP 覆盖层（键位说明，h 键开关）
void showHelp();
void hideHelp();
bool helpVisible();

void tick(uint32_t dtMs);                 // 合成当前模式 → push
}

