// 键位说明（HELP）
void drawHelp() {
    canvas.fillSprite(BG);
    canvas.setTextDatum(top_left);
    canvas.setTextSize(1);
    canvas.setTextColor(CLAWD, BG);
    canvas.drawString("KEY MAP", 6, 2);
    canvas.drawFastHLine(0, 12, canvasW, CLAWD);

